// A test text with true, false and unverifiable claims. Add the matching trusted fact
// "Acme Robotics was founded in Lisbon in 2012." to the truth_facts table to see VERIFIED from your own facts.
return [{ json: {
  source: 'manual-test',
  text: 'The Eiffel Tower is in Paris and was completed in 1889. It is about 900 metres tall. '
      + 'Acme Robotics was founded in Lisbon in 2012. I think this is a great place to visit in spring.'
} }];

// ===== CONFIG - everything you may want to change lives here =====
const CONFIG = {
  LLM_URL: 'http://localhost:11434/v1/chat/completions', // any OpenAI-compatible endpoint. Default: your own local Ollama (no API key)
  LLM_MODEL: 'qwen3:4b-instruct',   // a model you have pulled in Ollama (ollama pull qwen3:4b-instruct)
  USE_WIKIPEDIA: true,              // false = fully offline: only your own trusted facts are used as evidence
  WIKI_LANG: 'en',                  // Wikipedia language edition used for evidence
  MAX_CLAIMS: 8,                    // checkable claims verified per request
  MAX_TEXT_CHARS: 8000,             // longer texts are cut
  FLAG_RATIO: 0.34,                 // FLAG when more than this share of claims is UNSUPPORTED
  BLOCK_ON_CONTRADICTED: true       // BLOCK when any claim is CONTRADICTED by the evidence
};
const item = $input.first().json;
const fromWebhook = item.body !== undefined;
const body = fromWebhook ? (item.body || {}) : item;
const text = String(body.text || '').trim().slice(0, CONFIG.MAX_TEXT_CHARS);
if (!text) throw new Error('Send a JSON body with a "text" field that contains the AI output to check.');
return [{ json: {
  request_id: Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
  source: String(body.source || 'unknown').slice(0, 80),
  text,
  via: fromWebhook ? 'webhook' : 'manual',
  received_at: new Date().toISOString(),
  cfg: CONFIG
} }];

const req = $('Read Request & Config').first().json;
// Your own trusted facts (empty rows are ignored)
const facts = $input.all().map(i => i.json).filter(r => r && r.fact)
  .map(r => ({ fact: String(r.fact), topic: String(r.topic || '') }));
const system = 'You extract checkable factual claims from a text. A claim is checkable when it states a fact about the world: '
  + 'names, numbers, dates, places, events, definitions, quotes, product or company facts. '
  + 'Ignore opinions, feelings, advice, questions and promises. '
  + 'Rewrite each claim as one short standalone sentence that can be checked without the rest of the text, '
  + 'and give its main subject: only the name of the person, place, organisation or thing, without the property being claimed '
  + '(for example "Mount Everest", not "Mount Everest height"). '
  + 'Return JSON only, exactly: {"claims":[{"claim":"...","search":"..."}]}. If nothing is checkable return {"claims":[]}.';
return [{ json: { ...req, facts, llm_request: {
  model: req.cfg.LLM_MODEL, temperature: 0, stream: false, response_format: { type: 'json_object' },
  messages: [ { role: 'system', content: system }, { role: 'user', content: 'Text to analyse:\n<text>\n' + req.text + '\n</text>' } ]
} } }];

function parseJson(s) {
  s = String(s || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a < 0 || b < a) return null;
  try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; }
}
function llmText(res) {
  if (res && res.choices && res.choices[0] && res.choices[0].message) return res.choices[0].message.content;
  if (res && res.message) return res.message.content;
  return '';
}

const req = $('Build Claim Request').first().json;
const parsed = parseJson(llmText($input.first().json));
// Fail closed: if the model cannot analyse the text, the gate FLAGs it instead of letting it pass
if (!parsed) return [{ json: { no_claims: true, extract_failed: true, use_wiki: false } }];
const seen = new Set();
const claims = (Array.isArray(parsed.claims) ? parsed.claims : [])
  .map(c => ({ claim: String((c && c.claim) || (typeof c === 'string' ? c : '') || '').trim(), search: String((c && c.search) || '').trim() }))
  .filter(c => c.claim.length > 8 && !seen.has(c.claim) && seen.add(c.claim))
  .slice(0, req.cfg.MAX_CLAIMS);
// Match each claim with your own trusted facts by shared words (4+ letters)
const words = s => String(s).toLowerCase().match(/[\p{L}\p{N}]{4,}/gu) || [];
// The subject to search is taken from the claim itself when it names one (the longest run of capitalised words),
// because small models often add the property to the search term ("Eiffel Tower height") and miss the main page
const entity = s => (String(s).match(/\p{Lu}[\p{L}\p{N}'\u2019-]*(?:\s+\p{Lu}[\p{L}\p{N}'\u2019-]*)*/gu) || [])
  .map(x => x.replace(/^(The|A|An)\s+/, '').trim()).filter(x => x.length >= 3 && !/^(The|This|That|It|They|We|He|She|There)$/.test(x))
  .sort((a, b) => b.length - a.length)[0] || '';
const out = claims.map(({ claim, search }, i) => {
  const cw = new Set(words(claim));
  const trusted = req.facts.map(f => ({ f, s: words(f.fact).filter(w => cw.has(w)).length }))
    .filter(x => x.s >= 2).sort((a, b) => b.s - a.s).slice(0, 3).map(x => x.f.fact);
  return { json: { id: i + 1, claim, search: (entity(claim) || search || claim).slice(0, 120), trusted, use_wiki: req.cfg.USE_WIKIPEDIA, wiki_lang: req.cfg.WIKI_LANG } };
});
return out.length ? out : [{ json: { no_claims: true, extract_failed: false, use_wiki: false } }];

const req = $('Build Claim Request').first().json;
const plan = $('Plan Evidence').all().map(i => i.json);
const incoming = $input.all().map(i => i.json);   // Wikipedia answers in the same order, or the plan itself when Wikipedia is off
if (plan[0] && plan[0].no_claims) {
  return [{ json: { skip_judge: true, extract_failed: !!plan[0].extract_failed, claims: [] } }];
}
const claims = plan.map((p, idx) => {
  const r = incoming[idx] || {};
  const wiki = (r.query && r.query.pages) ? Object.values(r.query.pages)
    .map(pg => ({ title: pg.title, text: String(pg.extract || '').replace(/\s+/g, ' ').slice(0, 1200) })).filter(w => w.text) : [];
  const evidence = (p.trusted || []).map((t, k) => '[T' + (k + 1) + '] (trusted fact) ' + t)
    .concat(wiki.map((w, k) => '[W' + (k + 1) + '] (Wikipedia: ' + w.title + ') ' + w.text));
  return { id: p.id, claim: p.claim, search: p.search || '', evidence };
});
const block = claims.map(c => 'CLAIM ' + c.id + ': ' + c.claim + '\nEVIDENCE:\n' + (c.evidence.length ? c.evidence.join('\n') : '(none)')).join('\n\n');
const system = 'You are a strict fact verification judge. Judge each claim ONLY from the evidence given below it, never from your own knowledge. '
  + 'VERIFIED: the evidence clearly supports the claim. CONTRADICTED: the evidence clearly states the opposite. '
  + 'UNSUPPORTED: every other case, including no evidence. '
  + 'For VERIFIED and CONTRADICTED copy a short exact quote (at most 30 words) from that claim\'s evidence, character for character, '
  + 'and the quote must contain the words that prove or disprove this exact claim. '
  + 'Return JSON only, exactly: {"verdicts":[{"id":1,"verdict":"VERIFIED|UNSUPPORTED|CONTRADICTED","quote":"exact words or empty","reason":"one short sentence"}]}';
return [{ json: { skip_judge: false, extract_failed: false, claims, llm_url: req.cfg.LLM_URL, llm_request: {
  model: req.cfg.LLM_MODEL, temperature: 0, stream: false, response_format: { type: 'json_object' },
  messages: [ { role: 'system', content: system }, { role: 'user', content: block } ]
} } }];

function parseJson(s) {
  s = String(s || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a < 0 || b < a) return null;
  try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; }
}
function llmText(res) {
  if (res && res.choices && res.choices[0] && res.choices[0].message) return res.choices[0].message.content;
  if (res && res.message) return res.message.content;
  return '';
}

const req = $('Build Claim Request').first().json;
const ev = $('Collect Evidence').first().json;
const cfg = req.cfg;
let verdicts = [];
let judgeFailed = false;
if (!ev.skip_judge) {
  const parsed = parseJson(llmText($input.first().json));
  verdicts = parsed && Array.isArray(parsed.verdicts) ? parsed.verdicts : [];
  judgeFailed = !parsed || !Array.isArray(parsed.verdicts);
}
// THE JUDGE CANNOT LIE EITHER. A VERIFIED or CONTRADICTED verdict counts only when its quote is
// (1) grounded: at least 6 words in a row (or the whole quote) appear word for word in the evidence, covering 75% of the quote, and
// (2) relevant: a VERIFIED proof contains all numbers of the claim and half of its other words; a CONTRADICTED proof speaks about the same thing.
const toks = s => String(s || '').toLowerCase().match(/[\p{L}\p{N}]+/gu) || [];
function grounded(quote, evidence) {
  const q = toks(quote), e = toks(evidence);
  if (q.length < 4) return null;
  let best = { len: 0, start: 0 };
  for (let i = 0; i < q.length; i++) for (let j = 0; j < e.length; j++) {
    let k = 0; while (i + k < q.length && j + k < e.length && q[i + k] === e[j + k]) k++;
    if (k > best.len) best = { len: k, start: i };
  }
  if (best.len < Math.min(6, q.length) || best.len / q.length < 0.75) return null;
  return q.slice(best.start, best.start + best.len);
}
const claims = ev.claims.map(c => {
  const v = verdicts.find(x => Number(x.id) === c.id) || {};
  let verdict = String(v.verdict || 'UNSUPPORTED').toUpperCase();
  if (!['VERIFIED', 'UNSUPPORTED', 'CONTRADICTED'].includes(verdict)) verdict = 'UNSUPPORTED';
  const quote = String(v.quote || '').trim();
  let reason = String(v.reason || '');
  if (verdict !== 'UNSUPPORTED') {
    const span = grounded(quote, c.evidence.join(' '));
    const subject = new Set(toks(c.search));
    const keys = toks(c.claim).filter(w => !subject.has(w) && (w.length >= 4 || /\d/.test(w)));
    const nums = keys.filter(w => /\d/.test(w)), words = keys.filter(w => !/\d/.test(w));
    let relevant = false;
    if (!span) relevant = false;
    else if (verdict === 'VERIFIED') {
      // proof of a claim must contain all of its numbers, and at least half of its other words
      relevant = nums.every(n => span.includes(n)) && (!words.length || words.filter(w => span.includes(w)).length >= Math.ceil(words.length / 2));
    } else {
      // proof against a claim must speak about the same thing: a number when the claim has numbers, and one of its words
      relevant = (!nums.length || span.some(w => /\d/.test(w))) && (!words.length || span.some(w => words.includes(w)));
    }
    if (!span) { reason = 'Downgraded: the judge quote is not found word for word in the evidence. ' + reason; verdict = 'UNSUPPORTED'; }
    else if (keys.length && !relevant) { reason = 'Downgraded: the judge quote does not prove what this claim asserts. ' + reason; verdict = 'UNSUPPORTED'; }
  }
  if (verdict === 'UNSUPPORTED' && !reason.trim()) reason = judgeFailed ? 'The judge model gave no valid answer. Treated as unsupported (fail closed).' : 'No supporting evidence found.';
  return { id: c.id, claim: c.claim, verdict, quote: verdict === 'UNSUPPORTED' ? '' : quote, reason,
           evidence: c.evidence.map(e => e.slice(0, 4)).join(' ') || 'none' };
});
const n = k => claims.filter(c => c.verdict === k).length;
const total = claims.length, verified = n('VERIFIED'), unsupported = n('UNSUPPORTED'), contradicted = n('CONTRADICTED');
const reasons = [];
let decision = 'PASS';
if (ev.extract_failed) { decision = 'FLAG'; reasons.push('The model could not analyse the text (no valid JSON). Failing closed.'); }
if (contradicted > 0 && cfg.BLOCK_ON_CONTRADICTED) { decision = 'BLOCK'; reasons.push(contradicted + ' claim(s) contradicted by evidence.'); }
else if (total > 0 && unsupported / total > cfg.FLAG_RATIO) { decision = 'FLAG'; reasons.push(unsupported + ' of ' + total + ' claims unsupported by evidence.'); }
if (!total && !ev.extract_failed) reasons.push('No checkable factual claims found.');
const truth_score = ev.extract_failed ? 0 : (total ? Math.round(verified / total * 100) : 100);
const lines = claims.filter(c => c.verdict !== 'VERIFIED').map(c => '- [' + c.verdict + '] ' + c.claim + (c.quote ? '\n  Evidence: "' + c.quote + '"' : '') + (c.reason ? '\n  ' + c.reason : ''));
return [{ json: {
  request_id: req.request_id, source: req.source, via: req.via, checked_at: new Date().toISOString(),
  decision, truth_score, claims_total: total, verified, unsupported, contradicted, reasons, claims,
  text_excerpt: req.text.slice(0, 300),
  alert_text: 'TRUTH GATE: ' + decision + '\n\nSource: ' + req.source + '\nTruth score: ' + truth_score + '%\nReasons: ' + reasons.join(' ')
    + '\n\nClaims that need attention:\n' + (lines.join('\n') || '(none)') + '\n\nText (start):\n' + req.text.slice(0, 600)
} }];

// Weekly truth score per AI source: this week versus last week, plus the latest contradicted claims
const rows = $input.all().map(i => i.json).filter(r => r && r.checked_at);
const now = Date.now(), WEEK = 7 * 864e5;
const age = r => now - Date.parse(r.checked_at);
const cur = rows.filter(r => age(r) <= WEEK), prev = rows.filter(r => age(r) > WEEK && age(r) <= 2 * WEEK);
const avg = a => a.length ? Math.round(a.reduce((s, r) => s + Number(r.truth_score || 0), 0) / a.length) : null;
const sources = [...new Set(cur.map(r => r.source))].sort();
const esc = s => String(s).replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const rowsHtml = sources.map(s => {
  const c = cur.filter(r => r.source === s), p = prev.filter(r => r.source === s);
  const a = avg(c), b = avg(p);
  const trend = b === null ? 'new' : (a > b ? '+' + (a - b) : a < b ? '-' + (b - a) : '=');
  return '<tr><td>' + esc(s) + '</td><td>' + c.length + '</td><td><b>' + a + '%</b></td><td>' + trend + '</td><td>'
    + c.filter(r => r.decision === 'BLOCK').length + '</td><td>' + c.filter(r => r.decision === 'FLAG').length + '</td></tr>';
}).join('');
const worst = [];
for (const r of cur.slice().sort((x, y) => Date.parse(y.checked_at) - Date.parse(x.checked_at))) {
  let d = []; try { d = JSON.parse(r.details || '[]'); } catch (e) {}
  for (const c of d) if (c.verdict === 'CONTRADICTED' && worst.length < 5) worst.push('<li>' + esc(c.claim) + ' <i>(' + esc(r.source) + ')</i></li>');
}
const overall = avg(cur);
const status = overall === null ? 'NO CHECKS' : overall >= 80 ? 'HEALTHY' : 'ATTENTION';
const html = '<h2>Truth Gate - weekly report: ' + status + '</h2><p>Checks this week: ' + cur.length + ' | Overall truth score: '
  + (overall === null ? '-' : overall + '%') + '</p><table border="1" cellpadding="6" cellspacing="0"><tr><th>AI source</th><th>Checks</th>'
  + '<th>Truth score</th><th>vs last week</th><th>Blocked</th><th>Flagged</th></tr>' + (rowsHtml || '<tr><td colspan="6">No checks this week</td></tr>')
  + '</table><h3>Latest contradicted claims</h3><ul>' + (worst.join('') || '<li>None</li>') + '</ul>';
return [{ json: { subject: 'Truth Gate weekly report: ' + status + (overall === null ? '' : ' (' + overall + '%)'), html } }];
